//! Common Lisp (CFFI): the `azul` system (generated by
//! `doc/src/codegen/v2/lang_lisp`); the raw layer lives in `azul-internal`.
//!
//! Spellings: every C function is a `defcfun` named `%` + the kebab-cased C
//! symbol (`AzCssProperty_textColor` -> `azul-internal::%az-css-property-text-color`),
//! C-like enums are `defcenum` keywords (`:flex`, `:min-width`, reserved
//! names get `lisp-`: `:lisp-block`), a by-value struct is CFFI's plist of
//! its slots (`(list 'azul-internal::r 255 ...)`). A Vec is copied from a
//! foreign array (`css-vec` below), a String from a foreign UTF-8 buffer
//! (`css-str`, as `az-str` in `examples/lisp`).
//!
//! Limitation: CFFI builds a union only through its tagged helpers, not
//! from Lisp data, so a `CssPropertyValue<T>` alias / a `CssProperty`
//! without a constructor cannot be written by hand.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::{item_comments, item_doc, module_any, variant_ctor_method, ExprSyntax},
    CodegenBackend, GeneratedFile,
};

/// The Common Lisp printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Lisp;

/// `is_lisp_reserved` of `lang_lisp/mod.rs`.
const RESERVED: &[&str] = &[
    "block", "catch", "eval-when", "flet", "function", "go", "if", "labels", "let", "let*",
    "load-time-value", "locally", "macrolet", "multiple-value-call", "multiple-value-prog1",
    "progn", "progv", "quote", "return-from", "setq", "symbol-macrolet", "tagbody", "the",
    "throw", "unwind-protect", "t", "nil", "lambda",
];

/// `to_kebab_case` of `lang_lisp/mod.rs` (always `az-` prefixed).
fn kebab_az(name: &str) -> String {
    let body = name.strip_prefix("Az").unwrap_or(name);
    let mut out = String::from("az-");
    let mut prev_lower = false;
    let mut prev_digit = false;
    for c in body.chars() {
        if c == '_' {
            out.push('-');
            prev_lower = false;
            prev_digit = false;
        } else if c.is_uppercase() {
            if prev_lower || prev_digit {
                out.push('-');
            }
            out.push(c.to_ascii_lowercase());
            prev_lower = false;
            prev_digit = false;
        } else if c.is_ascii_digit() {
            out.push(c);
            prev_lower = false;
            prev_digit = true;
        } else {
            out.push(c);
            prev_lower = true;
            prev_digit = false;
        }
    }
    while out.contains("--") {
        out = out.replace("--", "-");
    }
    out
}

/// `ident_to_kebab` of `lang_lisp/mod.rs` (slot names, enum keywords).
fn kebab(name: &str) -> String {
    let mut out = String::new();
    let mut prev_lower = false;
    let mut prev_digit = false;
    for c in name.chars() {
        if c == '_' {
            if !out.is_empty() && !out.ends_with('-') {
                out.push('-');
            }
            prev_lower = false;
            prev_digit = false;
        } else if c.is_uppercase() {
            if (prev_lower || prev_digit) && !out.is_empty() && !out.ends_with('-') {
                out.push('-');
            }
            out.push(c.to_ascii_lowercase());
            prev_lower = false;
            prev_digit = false;
        } else {
            out.push(c);
            prev_lower = c.is_ascii_lowercase();
            prev_digit = c.is_ascii_digit();
        }
    }
    if RESERVED.contains(&out.as_str()) {
        format!("lisp-{out}")
    } else {
        out
    }
}

/// `raw_fn_name` of `lang_lisp/mod.rs`, qualified.
fn raw_fn(c_name: &str) -> String {
    format!("azul-internal::%{}", kebab_az(&c_name.replace('_', "-")))
}

/// `(f a b)`, one argument per line when `broken`.
fn form(f: String, args: Vec<Doc>, broken: bool) -> Doc {
    if args.is_empty() {
        return Doc::text(format!("({f})"));
    }
    let open = if broken {
        format!("({f}")
    } else {
        format!("({f} ")
    };
    Doc::list(&open, args, " ", ")", false, broken, false)
}

impl ExprSyntax for Lisp {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        if ty == Prim::F64 {
            format!("{text}d0")
        } else {
            text.to_string()
        }
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { "t" } else { "nil" })
    }

    fn string(&self, s: &str) -> Doc {
        let mut lit = String::from("\"");
        for c in s.chars() {
            if c == '"' || c == '\\' {
                lit.push('\\');
            }
            lit.push(c);
        }
        lit.push('"');
        form("css-str".to_string(), vec![Doc::text(lit)], false)
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        form(raw_fn(&format!("Az{class}_{}", snake_to_lower_camel(method))), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!(":{}", kebab(variant))),
            EnumShape::Tagged => form(
                raw_fn(&format!("Az{ty}_{}", variant_ctor_method(variant))),
                args,
                broken,
            ),
            // unreachable: `limitation` rejects hand-built unions
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                Doc::text(format!("(error \"cannot build {ty}::{variant}\")"))
            }
        }
    }

    fn strukt(&self, _ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let mut items = Vec::new();
        for (k, v) in fields {
            items.push(Doc::text(format!("'azul-internal::{}", kebab(&k))));
            items.push(v);
        }
        form("list".to_string(), items, broken)
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return form(raw_fn(&format!("Az{ty}_create")), Vec::new(), false);
        }
        form(
            "css-vec".to_string(),
            vec![
                Doc::text(format!("#'{}", raw_fn(&format!("Az{ty}_copyFromPtr")))),
                Doc::text(format!("'azul-internal::{}", kebab_az(elem))),
                form("list".to_string(), items, broken),
            ],
            broken,
        )
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("(error \"not expressible: {}\")", what.replace(['"', '\\'], "'")))
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Variant {
                ty,
                shape: EnumShape::Generic { .. } | EnumShape::TaggedShadowed,
                ..
            } => Some(format!(
                "CFFI cannot build the union `{ty}` from Lisp data (no constructor function)"
            )),
            Expr::Float { text, .. } if text == "nan" || text.ends_with("inf") => {
                Some("NaN / infinity has no portable Common Lisp literal".to_string())
            }
            _ => None,
        }
    }
}

const HELPERS: &str = r#"(defun css-type (name)
  "The CFFI type of the api.json type NAME: its union, struct or enum."
  (or (find-if (lambda (spec) (ignore-errors (cffi:foreign-type-size spec)))
               (list (list :union name) (list :struct name)))
      name))

(defun css-vec (copy-fn elem items)
  "Copies ITEMS into a foreign array of ELEM; COPY-FN clones them into a Vec."
  (let ((type (css-type elem))
        (n (length items)))
    (cffi:with-foreign-object (arr type n)
      (loop for item in items
            for i from 0
            do (setf (cffi:mem-aref arr type i) item))
      (funcall copy-fn arr n))))
"#;

const CSS_STR: &str = r#"(defun css-str (s)
  "An AzString holding the UTF-8 bytes of S."
  (cffi:with-foreign-string ((buf len) s :null-terminated-p nil)
    (azul-internal::%az-string-copy-from-bytes buf 0 len)))
"#;

fn fn_name(item: &Item) -> String {
    item.name.kebab()
}

fn item_fn(item: &Item) -> (bool, String) {
    let mut out = String::new();
    for line in &item_comments(&Lisp, item) {
        out.push_str(&format!(";; {line}\n"));
    }
    let name = fn_name(item);
    match item_doc(&Lisp, item) {
        Ok(doc) => {
            out.push_str(&format!("(defun {name} ()\n  {})\n", render(&doc, "  ", 1)));
            (true, out)
        }
        Err(reason) => {
            out.push_str(&format!(
                ";; {name}: not expressible with the Common Lisp bindings: {reason}\n"
            ));
            (false, out)
        }
    }
}

impl CodegenBackend for Lisp {
    fn lang(&self) -> &'static str {
        "lisp"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["common-lisp", "cl", "sbcl"]
    }

    fn display_name(&self) -> &'static str {
        "Common Lisp"
    }

    fn extension(&self) -> &'static str {
        "lisp"
    }

    fn emit_module(&self, m: &Module) -> String {
        let fns: Vec<(bool, String, String)> = m
            .items
            .iter()
            .map(|i| {
                let (ok, body) = item_fn(i);
                (ok, fn_name(i), body)
            })
            .collect();
        let mut out = String::from(
            ";;;; Generated by azul-css codegen (Common Lisp). Do not edit by hand.\n(defpackage \
             #:azul-styles\n  (:use #:cl)\n  (:export",
        );
        for (ok, name, _) in &fns {
            if *ok {
                out.push_str(&format!(" #:{name}"));
            }
        }
        out.push_str("))\n\n(in-package #:azul-styles)\n");
        if module_any(m, &|e| matches!(e, Expr::Vec { .. })) {
            out.push('\n');
            out.push_str(HELPERS);
        }
        if module_any(m, &|e| matches!(e, Expr::Str(_))) {
            out.push('\n');
            out.push_str(CSS_STR);
        }
        for (_, _, body) in &fns {
            out.push('\n');
            out.push_str(body);
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            ";;;; Put target/codegen/azul.asd + azul.lisp where ASDF finds them and libazul \
             on the\n;;;; loader path, then:\n;;;;   sbcl --eval '(asdf:load-system \
             :azul-styles)' --eval '(azul-styles::main)' --quit\n(in-package \
             #:azul-styles)\n\n(defun main ()",
        );
        for item in m.items.iter().filter(|i| item_fn(i).0) {
            let name = fn_name(item);
            main.push_str(&format!(
                "\n  (format t \"{name}: ~a properties~%\" (getf ({name}) 'azul-internal::len))"
            ));
        }
        main.push_str(")\n");
        vec![
            GeneratedFile {
                path: "azul-styles.asd".to_string(),
                contents: ASD.to_string(),
            },
            GeneratedFile {
                path: "styles.lisp".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.lisp".to_string(),
                contents: main,
            },
        ]
    }
}

const ASD: &str = r#"(asdf:defsystem #:azul-styles
  :description "Styles generated by azul-css codegen"
  :depends-on (#:azul #:cffi)
  :serial t
  :components ((:file "styles") (:file "main")))
"#;
